package lsm_test

import("fmt";"testing";"edgesync/pkg/kv";"edgesync/pkg/lsm")
func openEngine(t testing.TB,dir string,memBytes int)*lsm.Engine{t.Helper();e,err:=lsm.Open(lsm.Options{Dir:dir,MemtableBytes:memBytes,CompactAt:3});if err!=nil{t.Fatal(err)};return e}
func TestWALRecovery(t *testing.T){dir:=t.TempDir();e:=openEngine(t,dir,1<<20);for i:=0;i<100;i++{if err:=e.Put([]byte(fmt.Sprintf("order:%03d",i)),[]byte("CREATED"));err!=nil{t.Fatal(err)}};_=e.Delete([]byte("order:050"));_=e.Close();e=openEngine(t,dir,1<<20);defer e.Close();if v,err:=e.Get([]byte("order:010"));err!=nil||string(v)!="CREATED"{t.Fatalf("lost write %q %v",v,err)};if _,err:=e.Get([]byte("order:050"));err!=kv.ErrNotFound{t.Fatalf("delete not recovered: %v",err)}}
func TestFlushCompactionAndTombstones(t *testing.T){dir:=t.TempDir();e:=openEngine(t,dir,512);for i:=0;i<500;i++{if err:=e.Put([]byte(fmt.Sprintf("k%04d",i)),[]byte(fmt.Sprintf("v%d",i)));err!=nil{t.Fatal(err)}};for i:=0;i<500;i+=2{if err:=e.Delete([]byte(fmt.Sprintf("k%04d",i)));err!=nil{t.Fatal(err)}};st:=e.Stats();if st.Flushes==0||st.Compactions==0{t.Fatalf("expected flushes and compactions, got %+v",st)};check:=func(){for i:=0;i<500;i++{_,err:=e.Get([]byte(fmt.Sprintf("k%04d",i)));if i%2==0&&err!=kv.ErrNotFound{t.Fatalf("key %d should be deleted: %v",i,err)};if i%2==1&&err!=nil{t.Fatalf("key %d lost: %v",i,err)}};pairs,err:=e.Scan([]byte("k"),0);if err!=nil||len(pairs)!=250{t.Fatalf("scan count=%d err=%v",len(pairs),err)}};check();_=e.Close();e=openEngine(t,dir,512);defer e.Close();check()}
func BenchmarkPut(b *testing.B){e,err:=lsm.Open(lsm.Options{Dir:b.TempDir(),MemtableBytes:4<<20});if err!=nil{b.Fatal(err)};defer e.Close();v:=make([]byte,100);b.ReportAllocs();b.ResetTimer();for i:=0;i<b.N;i++{if err:=e.Put([]byte(fmt.Sprintf("key-%012d",i)),v);err!=nil{b.Fatal(err)}}}
